//! The system prompt each mode gives a prompt's hidden anchor. Each is a
//! template saved with the project, one file per mode in
//! `.suspense/system-prompts`, edited by hand or in the settings window (see
//! [`crate::settings_window`]). In a template, `${CODE_LOCATION}` and
//! `${SPEC_LOCATION}` stand for `codeRoot` and `root` in `piton.config.pi`,
//! and `${PITON_FLUENCY}` for the project's Piton fluency (see
//! [`crate::piton_fluency`]), written like Piton interpolations and filled in
//! before the prompt is compiled. Otherwise, like the prompt it is sent with, a template is Piton
//! prose, so it can reference the spec.

use std::fs;
use std::io::ErrorKind;
use std::path::{Path, PathBuf};

use anyhow::{Context as _, Result};

use crate::chat_input::SendMode;
use crate::hidden_anchor::APP_DIR;

pub const CODE_LOCATION: &str = "${CODE_LOCATION}";
pub const SPEC_LOCATION: &str = "${SPEC_LOCATION}";
pub const PITON_FLUENCY: &str = "${PITON_FLUENCY}";

const DIR: &str = "system-prompts";

/// The template a mode starts with, and is reset to: this repository's own
/// `.suspense/system-prompts`, baked in when the application is built, so
/// editing those files changes the defaults the next build ships with.
pub fn default_template(mode: SendMode) -> &'static str {
    macro_rules! baked {
        ($key:literal) => {
            include_str!(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/.suspense/system-prompts/",
                $key,
                ".md"
            ))
        };
    }
    // Trimmed as a saved template is when it loads, so a template left as
    // the default reads as the default.
    match mode {
        SendMode::Code => baked!("code"),
        SendMode::Both => baked!("combined"),
        SendMode::Spec => baked!("spec"),
        SendMode::Ask => baked!("ask"),
    }
    .trim_end()
}

/// The directory the project's templates are saved in.
pub fn dir(project_dir: &Path) -> PathBuf {
    project_dir.join(APP_DIR).join(DIR)
}

/// The file `mode`'s template is saved in.
pub fn file(mode: SendMode, project_dir: &Path) -> PathBuf {
    dir(project_dir).join(format!("{}.md", mode.key()))
}

/// `mode`'s template for the project: its saved file, or the default while
/// there is none.
pub fn load(mode: SendMode, project_dir: &Path) -> Result<String> {
    let file = file(mode, project_dir);
    match fs::read_to_string(&file) {
        Ok(template) => Ok(template.trim_end().to_string()),
        Err(err) if err.kind() == ErrorKind::NotFound => Ok(default_template(mode).to_string()),
        Err(err) => Err(err).with_context(|| format!("could not read {}", file.display())),
    }
}

/// Saves `template` as `mode`'s for the project.
pub fn save(mode: SendMode, template: &str, project_dir: &Path) -> Result<()> {
    let dir = dir(project_dir);
    fs::create_dir_all(&dir).with_context(|| format!("could not create {}", dir.display()))?;
    let file = file(mode, project_dir);
    fs::write(&file, format!("{}\n", template.trim_end()))
        .with_context(|| format!("could not save {}", file.display()))
}

/// Saves the default template of every mode the project has no file for, so
/// each can be found and edited by hand.
pub fn save_missing(project_dir: &Path) -> Result<()> {
    for mode in SendMode::ALL {
        if !file(mode, project_dir).exists() {
            save(mode, default_template(mode), project_dir)?;
        }
    }
    Ok(())
}

/// `template` with the code and spec locations and the Piton fluency filled
/// in; an empty fluency leaves no blank lines at the end.
pub fn fill(template: &str, code: &str, spec: &str, fluency: &str) -> String {
    template
        .replace(CODE_LOCATION, code)
        .replace(SPEC_LOCATION, spec)
        .replace(PITON_FLUENCY, fluency)
        .trim_end()
        .to_string()
}

#[cfg(test)]
mod tests {
    use std::fs;
/// name it starts with.
#[derive(Debug, PartialEq)]
enum Piece<'a> {
    Text(&'a str),
    Reference(&'a str, &'a str),
}

/// `line` split into text and the `@{Name.path}` and `${Name.path}` in it.
fn pieces(line: &str) -> Vec<Piece<'_>> {
    let mut pieces = Vec::new();
    let mut text_start = 0;
    let mut at = 0;
    while at < line.len() {
        let rest = &line[at..];
        let reference = (rest.starts_with("@{") || rest.starts_with("${"))
            .then(|| rest[2..].find('}'))
            .flatten()
            .map(|close| &rest[2..2 + close])
            .filter(|path| is_identifier_path(path));
        match reference {
            Some(path) => {
                if text_start < at {
                    pieces.push(Piece::Text(&line[text_start..at]));
                }
                let end = at + 2 + path.len() + 1;
                let name = path.split('.').next().unwrap_or(path);
                pieces.push(Piece::Reference(&line[at..end], name));
                at = end;
                text_start = end;
            }
            None => at += rest.chars().next().map_or(1, char::len_utf8),
        }
    }
    if text_start < line.len() {
        pieces.push(Piece::Text(&line[text_start..]));
    }
    pieces
}

/// Whether `path` is a dotted path of identifiers, each perhaps with
/// kebab-case tails, as a Piton reference is.
fn is_identifier_path(path: &str) -> bool {
    !path.is_empty()
        && path.split('.').all(|segment| {
            let mut parts = segment.split('-');
            let head = parts.next().unwrap_or_default();
            head.chars()
                .next()
                .is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
                && head.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
                && parts.all(|tail| {
                    !tail.is_empty() && tail.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
                })
        })
}

/// `line` for `piton lsp`: references, and one being typed, kept as they are;
/// letters, digits, and spaces between words kept; anything else, and
/// leading whitespace, replaced with as many underscores as it is UTF-16 units
/// long, so every position in the line stays where it was.
fn blank_for_lsp(line: &str) -> String {
    let mut out = String::with_capacity(line.len());
    let mut at = 0;
    while at < line.len() {
        let rest = &line[at..];
        if rest.starts_with("@{") || rest.starts_with("${") {
            let name_len = rest[2..]
                .find(|c: char| !(c.is_ascii_alphanumeric() || matches!(c, '_' | '.' | '-')))
                .unwrap_or(rest.len() - 2);
            let mut end = 2 + name_len;
            if rest[end..].starts_with('}') {
                end += 1;
            }
            out.push_str(&rest[..end]);
            at += end;
            continue;
        }
        let c = rest.chars().next().unwrap_or(' ');
        let leading = out.chars().all(|c| c == '_');
        if c.is_alphanumeric() && c.len_utf16() == 1 || (c == ' ' && !leading) {
            out.push(c);
        } else {
            out.extend(std::iter::repeat_n('_', c.len_utf16()));
        }
        at += c.len_utf8();
    }
    out
}

/// The system prompt a prompt sent in `mode` is given: the project's template
/// for it (see [`crate::system_prompts`]), naming the code and spec locations
/// set in its `piton.config.pi`, and with the project's Piton `fluency`. A
/// template that is empty once filled in gives none.
pub fn system_prompt(mode: SendMode, project_dir: &Path, fluency: &str) -> Result<Option<String>> {
    let template = system_prompts::load(mode, project_dir)?;
    if template.trim().is_empty() {
        return Ok(None);
    }
    let code = config_value(project_dir, "codeRoot")?;
    let spec = config_value(project_dir, "root")?;
    let filled = system_prompts::fill(&template, &code, &spec, fluency);
    Ok((!filled.trim().is_empty()).then_some(filled))
}

/// The mode of a prompt saved before modes were, read from the default system
/// prompt it was given; `None` for one sent without a system prompt, or with
/// an edited one.
pub fn mode_of(system_prompt: &str) -> Option<SendMode> {
    [
        ("We're working on the code ", SendMode::Code),
        ("We're working on both ", SendMode::Both),
        ("We're working on the spec ", SendMode::Spec),
        ("We're only asking a question ", SendMode::Ask),
    ]
    .into_iter()
    .find_map(|(start, mode)| system_prompt.starts_with(start).then_some(mode))
}

/// The path the chat input's unsent text is presented to `piton lsp` under.
/// Nothing is written there. It sits inside the spec root because `piton lsp`
/// only resolves imports, and offers auto-imports, for documents under it.
pub fn draft_path(project_dir: &Path) -> PathBuf {
    let spec_root = spec_root(project_dir).unwrap_or_default();
    project_dir.join(spec_root).join(".suspense-draft.pi")
}

/// The project's prompt history directory.
pub fn history_dir(project_dir: &Path) -> PathBuf {
    project_dir.join(APP_DIR).join(HISTORY_DIR)
}

/// Saves `prompt`, as `anchor`'s source, to the project's prompt history.
pub fn save(anchor: &HiddenAnchor, prompt: &str, project_dir: &Path) -> Result<PathBuf> {
    save_in(&history_dir(project_dir), anchor, prompt)
}

/// Compiles `prompt`, as `anchor`'s source, without keeping it: saved only
/// for as long as it takes to compile, out of the history.
pub fn preview(anchor: &HiddenAnchor, prompt: &str, project_dir: &Path) -> Result<CompiledPrompt> {
    let dir = project_dir.join(APP_DIR).join("preview");
    let file = save_in(&dir, anchor, prompt)?;
    let compiled = compile(anchor, &file, project_dir);
    fs::remove_file(&file).ok();
    // Gone too once nothing else is being previewed.
    fs::remove_dir(&dir).ok();
    compiled
}

/// Where the project's questions are saved, apart from the history.
pub fn asks_dir(project_dir: &Path) -> PathBuf {
    project_dir.join(APP_DIR).join(ASKS_DIR)
}

/// Saves a question, as `anchor`'s source, where it can be compiled without
/// joining the prompt history.
pub fn save_ask(anchor: &HiddenAnchor, prompt: &str, project_dir: &Path) -> Result<PathBuf> {
    save_in(&asks_dir(project_dir), anchor, prompt)
}

fn save_in(dir: &Path, anchor: &HiddenAnchor, prompt: &str) -> Result<PathBuf> {
    fs::create_dir_all(dir).with_context(|| format!("could not create {}", dir.display()))?;
    let sent_at = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |elapsed| elapsed.as_secs());
    let file = dir.join(format!("{sent_at}-{}.pi", anchor.name));
    fs::write(&file, anchor.source(prompt))
        .with_context(|| format!("could not save {}", file.display()))?;
    Ok(file)
}

/// Compiles `file`, a saved `anchor`, and returns its compiled prompt text.
pub fn compile(anchor: &HiddenAnchor, file: &Path, project_dir: &Path) -> Result<CompiledPrompt> {
    let output = Command::new("piton")
        .args(["compile", "--stdout"])
        .arg(file)
        .current_dir(project_dir)
        .output()
        .context("could not run `piton compile`")?;
    if !output.status.success() {
        let mut message = String::from_utf8_lossy(&output.stdout).into_owned();
        message.push_str(&String::from_utf8_lossy(&output.stderr));
        return Err(anyhow!("{}", message.trim()));
    }

    let compiled: Value =
        serde_json::from_slice(&output.stdout).context("`piton compile` did not print JSON")?;
    let compiled = compiled
        .get(&anchor.name)
        .ok_or_else(|| anyhow!("the compiled output has no {}", anchor.name))?;
    let user_prompt = compiled
        .get("userPrompt")
        .ok_or_else(|| anyhow!("the compiled anchor has no userPrompt"))?;
    // Each piece of attached text compiles to the list of its lines.
    let attached_text: Vec<String> = compiled
        .get("attachedText")
        .and_then(Value::as_array)
        .map(|pieces| {
            pieces
                .iter()
                .map(|piece| match piece {
                    Value::Array(lines) => lines
                        .iter()
                        .map(|line| line.as_str().unwrap_or_default())
                        .collect::<Vec<_>>()
                        .join("\n"),
                    other => prose(other),
                })
                .collect()
        })
        .unwrap_or_default();
    Ok(CompiledPrompt {
        user_prompt: with_attached_text(&text_of(user_prompt), &attached_text),
        system_prompt: compiled.get("systemPrompt").map(text_of),
    })
}

/// Reads the spec root (`root:`) from the project's `piton.config.pi`.
fn spec_root(project_dir: &Path) -> Result<PathBuf> {
    config_value(project_dir, "root").map(PathBuf::from)
}

/// The spec location, as a directory of the project, when its
/// `piton.config.pi` names one.
pub fn spec_dir(project_dir: &Path) -> Option<PathBuf> {
    let root = spec_root(project_dir).ok()?;
    Some(project_dir.join(root.strip_prefix("./").unwrap_or(&root)))
}

/// The spec files `imports` import from: each module under the spec location,
/// as `<module>.pi` or `<module>/index.pi`, whichever exists. Packages, and
/// modules with no file, are left out.
pub fn spec_files(imports: &Imports, project_dir: &Path) -> Vec<PathBuf> {
    let Some(root) = spec_dir(project_dir) else {
        return Vec::new();
    };
    imports
        .modules()
        .filter_map(|module| {
            let module = module.strip_prefix('/')?;
            [
                root.join(format!("{module}.pi")),
//! The prompt history on disk. Each sent prompt is saved in the project's
//! `.suspense/history` as its hidden anchor's source (see
//! [`crate::hidden_anchor::save`]). Once its run is over, what came of it is
//! saved beside it in a `.json` file of the same name: the compiled prompt the
//! harness received, the harness's output line by line, and any error. Opening
//! the project again replays them into the tasks they were.

use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context as _, Result};
use serde::{Deserialize, Serialize};
use serde_json::Value;

use crate::harness::HarnessEvent;
use crate::hidden_anchor::{self, HiddenAnchor};

/// What came of a sent prompt, as saved beside it.
#[derive(Debug, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RunRecord {
    /// The compiled `userPrompt` the harness received; none if the prompt did
    /// not compile.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub user_prompt: Option<String>,
    /// Each line the harness printed, as JSON where it was, else as a string.
    #[serde(default)]
    pub output: Vec<Value>,
    /// Why the run failed, when the harness's output does not say.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
}

impl RunRecord {
    /// Keeps what of a harness event cannot be replayed from its output: the
    /// raw lines themselves, and a failure outside them.
    pub fn note(&mut self, event: &HarnessEvent) {
        match event {
            HarnessEvent::Output(line) => self
                .output
                .push(serde_json::from_str(line).unwrap_or_else(|_| Value::String(line.clone()))),
            HarnessEvent::Failed(error) => self.error = Some(error.clone()),
            _ => {}
        }
    }
}

/// A prompt in the history, and its run's record if one was saved.
pub struct SavedPrompt {
    pub anchor: HiddenAnchor,
    pub text: String,
    pub record: Option<RunRecord>,
}

