80% of erach other.

Then build the spec and execute the prompt directly on the code using a unified plan.

Make sure that you write both code and spec.

Links to .claude/reference/… in the prompt are the spec for what they name. Read each one before changing anything it covers.

${PITON_FLUENCY}

---
    use std::fs;
    use std::path::Path;

    use super::{PITON_FLUENCY, default_template, file, fill, load, save, save_missing};
    use crate::chat_input::SendMode;

    /// Each mode's default is this repository's own saved template for it,
    /// tells the harness to follow references, ends with the Piton fluency,
    /// and fills in the configured locations and the fluency.
    #[test]
    fn defaults_are_this_repositorys_templates() {
        let manifest = Path::new(env!("CARGO_MANIFEST_DIR"));
        for mode in SendMode::ALL {
            let saved = fs::read_to_string(file(mode, manifest)).unwrap();
            assert_eq!(default_template(mode), saved.trim_end(), "{mode:?}");
            assert!(
                default_template(mode).contains(
                    "Links to .claude/reference/… in the prompt are the spec for what they \
                     name. Read each one before changing anything it covers."
                ),
                "{mode:?} doesn't say to follow references"
            );
            assert!(
                default_template(mode).ends_with(&format!("\n\n{PITON_FLUENCY}")),
                "{mode:?} doesn't end with the fluency"
            );
            let filled = fill(default_template(mode), "./src", "./spec", "# Piton fluency");
            assert!(
                !filled.contains("${"),
                "{mode:?} left a placeholder: {filled}"
            );
            assert!(
                filled.ends_with("\n\n# Piton fluency"),
                "{mode:?}: {filled}"
            );
            // Without piton, nothing is left in its place.
            let without = fill(default_template(mode), "./src", "./spec", "");
            assert!(without.ends_with("covers."), "{mode:?}: {without}");
        }
        assert!(
            fill(default_template(SendMode::Code), "./src", "./spec", "").contains("./src"),
            "the code location isn't filled in"
        );
    }

    /// Templates load as their default until saved, and as saved after;
    /// saving the missing ones leaves an edited one alone.
    #[test]
    fn templates_are_saved_with_the_project() {
        let project_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/system-prompts-test");
        fs::remove_dir_all(&project_dir).ok();

        assert_eq!(
            load(SendMode::Spec, &project_dir).unwrap(),
            default_template(SendMode::Spec)
        );
        save(
            SendMode::Spec,
            "Only the spec, in ${SPEC_LOCATION}.\n\n",
            &project_dir,
        )
        .unwrap();
        assert_eq!(
            load(SendMode::Spec, &project_dir).unwrap(),
            "Only the spec, in ${SPEC_LOCATION}."
        );

        save_missing(&project_dir).unwrap();
        for mode in SendMode::ALL {
            assert!(file(mode, &project_dir).exists(), "{mode:?} was not saved");
        }
        assert_eq!(
            load(SendMode::Spec, &project_dir).unwrap(),
            "Only the spec, in ${SPEC_LOCATION}."
        );
        assert_eq!(
            load(SendMode::Ask, &project_dir).unwrap(),
            default_template(SendMode::Ask)
        );
    }
}

